export type SemanticIconProps = {
  size?: number;
  color?: string;
  className?: string;
  strokeWidth?: number;
  weight?: 'thin' | 'light' | 'regular' | 'bold' | 'fill' | 'duotone';
  accessibilityLabel?: string;
  decorative?: boolean;
  [key: string]: unknown;
};
export type SemanticIconComponent = React.ComponentType<SemanticIconProps>;

function createSemanticIcon(Glyph: React.ComponentType<any>, displayName: string): SemanticIconComponent {
  const Component = React.forwardRef<any, SemanticIconProps>(function SemanticIcon(
    {
      size = 16,
      color = 'currentColor',
      className,
      strokeWidth = 2,
      weight = 'regular',
      accessibilityLabel,
      decorative = !accessibilityLabel,
      ...props
    },
    ref
  ) {
    return <Glyph ref={ref} size={size} color={color} className={className} weight={weight} accessibilityLabel={decorative ? undefined : accessibilityLabel} aria-hidden={decorative} {...props} />;
  });
  Component.displayName = displayName;
  return Component;
}

